import{_ as e,o,c as r,ag as a}from"./chunks/framework.qXLDknWC.js";const p=JSON.parse('{"title":"Lorebook Editor","description":"","frontmatter":{},"headers":[],"relativePath":"features/lorebook-editor.md","filePath":"features/lorebook-editor.md"}'),i={name:"features/lorebook-editor.md"};function n(l,t,s,d,h,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="lorebook-editor" tabindex="-1">Lorebook Editor <a class="header-anchor" href="#lorebook-editor" aria-label="Permalink to &quot;Lorebook Editor&quot;">​</a></h1><p>The <strong>Lorebook</strong> tab (also called World Info) provides a dedicated two-panel interface for managing character lore entries — extra information that gets injected into the AI&#39;s context based on keyword triggers.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Lorebook entries affect how an AI plays your character during roleplay. For a quick overview of each field, see <a href="/CharacterVault/docs/getting-started/creating-characters#lorebook--world-info">Creating &amp; Editing Characters → Lorebook</a>.</p></div><h2 id="two-panel-layout" tabindex="-1">Two-Panel Layout <a class="header-anchor" href="#two-panel-layout" aria-label="Permalink to &quot;Two-Panel Layout&quot;">​</a></h2><p>The lorebook editor uses a sidebar + detail layout:</p><ul><li><strong>Left sidebar</strong> — Lists all entries with search, context toggles, and add/delete controls.</li><li><strong>Right panel</strong> — Full detail editor for the selected entry.</li></ul><p>On mobile, the sidebar and detail panel switch between each other with a back button.</p><h2 id="entry-list-sidebar" tabindex="-1">Entry List Sidebar <a class="header-anchor" href="#entry-list-sidebar" aria-label="Permalink to &quot;Entry List Sidebar&quot;">​</a></h2><p>Each entry in the sidebar shows:</p><ul><li><strong>Entry name</strong> (or &quot;Entry N&quot; if unnamed)</li><li><strong>Key count</strong> and <strong>token count</strong> for the selected entry</li><li><strong>Context toggle</strong> (eye icon) — quickly include or exclude the entry from AI context without disabling it entirely</li><li><strong>Delete button</strong> — removes the entry (with confirmation)</li></ul><h3 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h3><p>Use the search bar at the top of the sidebar to filter entries by name, content, or trigger keys. A result count appears when a search is active.</p><h3 id="book-settings" tabindex="-1">Book Settings <a class="header-anchor" href="#book-settings" aria-label="Permalink to &quot;Book Settings&quot;">​</a></h3><p>Click <strong>Book Settings</strong> at the top of the sidebar to expand:</p><ul><li><strong>Book Name</strong> — A display name for the lorebook (e.g., &quot;Character Lorebook&quot;).</li><li><strong>Description</strong> — A brief description of the lorebook&#39;s purpose.</li><li><strong>Context Visibility</strong> — <strong>Enable All</strong> / <strong>Disable All</strong> buttons to quickly toggle whether every entry is included in AI context.</li></ul><h3 id="adding-entries" tabindex="-1">Adding Entries <a class="header-anchor" href="#adding-entries" aria-label="Permalink to &quot;Adding Entries&quot;">​</a></h3><p>Click <strong>New Entry</strong> at the bottom of the sidebar to add a blank entry. The new entry is automatically selected for editing.</p><h2 id="entry-detail-editor" tabindex="-1">Entry Detail Editor <a class="header-anchor" href="#entry-detail-editor" aria-label="Permalink to &quot;Entry Detail Editor&quot;">​</a></h2><p>Selecting an entry in the sidebar opens its full editor on the right with these fields:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Entry Name</strong></td><td style="text-align:left;">Display name for the entry (optional)</td></tr><tr><td style="text-align:left;"><strong>Trigger Keys</strong></td><td style="text-align:left;">Comma-separated keywords that activate the entry during AI conversations</td></tr><tr><td style="text-align:left;"><strong>Priority</strong></td><td style="text-align:left;">Determines insertion order when multiple entries fire (lower = higher priority)</td></tr><tr><td style="text-align:left;"><strong>Position</strong></td><td style="text-align:left;">Where the entry content is inserted in the prompt</td></tr><tr><td style="text-align:left;"><strong>Enabled</strong></td><td style="text-align:left;">Whether the entry is active</td></tr><tr><td style="text-align:left;"><strong>Case Sensitive</strong></td><td style="text-align:left;">Require exact case matching on trigger keys</td></tr><tr><td style="text-align:left;"><strong>Constant</strong></td><td style="text-align:left;">Always include this entry in context, regardless of keyword triggers</td></tr><tr><td style="text-align:left;"><strong>Content</strong></td><td style="text-align:left;">The text injected when the entry activates — full CodeMirror editor with AI toolbar</td></tr><tr><td style="text-align:left;"><strong>Comment</strong></td><td style="text-align:left;">Internal notes about this entry (not used in AI output)</td></tr></tbody></table><h3 id="position-options" tabindex="-1">Position Options <a class="header-anchor" href="#position-options" aria-label="Permalink to &quot;Position Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Position</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Before Character</strong></td><td style="text-align:left;">Inserted before the character description</td></tr><tr><td style="text-align:left;"><strong>After Character</strong></td><td style="text-align:left;">Inserted after the character description</td></tr><tr><td style="text-align:left;"><strong>Before Example</strong></td><td style="text-align:left;">Inserted before the dialogue examples</td></tr><tr><td style="text-align:left;"><strong>After Example</strong></td><td style="text-align:left;">Inserted after the dialogue examples</td></tr></tbody></table><h3 id="ai-key-generation" tabindex="-1">AI Key Generation <a class="header-anchor" href="#ai-key-generation" aria-label="Permalink to &quot;AI Key Generation&quot;">​</a></h3><p>The <strong>sparkle icon</strong> (✨) next to the Trigger Keys label uses AI to generate trigger keywords from the entry&#39;s content. This is useful when you&#39;ve written lore content but aren&#39;t sure which keywords should activate it.</p><ol><li>Write your entry content first.</li><li>Click the ✨ button next to Trigger Keys.</li><li>The AI analyzes the content and generates 2–5 comma-separated trigger keywords.</li><li>Generated keys are <strong>merged</strong> with any existing keys (duplicates are ignored).</li><li>Click the ✨ button again while generating to abort (15-second timeout).</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>AI key generation requires an AI provider to be configured. See <a href="/CharacterVault/docs/configuration/ai-setup">AI Setup</a>.</p><p>If you mapped the <strong>Custom</strong> prompt to a specific endpoint/model under <strong>Settings → Prompts</strong>, key generation uses that mapping; otherwise it uses your global AI Config model.</p></div><h3 id="context-visibility" tabindex="-1">Context Visibility <a class="header-anchor" href="#context-visibility" aria-label="Permalink to &quot;Context Visibility&quot;">​</a></h3><p>The eye icon on each entry in the sidebar controls whether that entry is included when the AI assistant (Orion) and AI toolbar operations use character context. This is separate from the <strong>Enabled</strong> toggle:</p><ul><li><strong>Enabled</strong> — Controls whether the entry activates during AI roleplay (in SillyTavern, etc.).</li><li><strong>Context</strong> (eye icon) — Controls whether the entry content is sent to Character Vault&#39;s AI assistant as context.</li></ul><p>An entry can be enabled for roleplay but excluded from Orion&#39;s context, or vice versa.</p><h2 id="import-export" tabindex="-1">Import &amp; Export <a class="header-anchor" href="#import-export" aria-label="Permalink to &quot;Import &amp; Export&quot;">​</a></h2><p>You can import and export lorebooks independently of character cards. This is useful for:</p><ul><li>Sharing lorebooks between characters</li><li>Backing up world info separately</li><li>Importing lorebooks from other tools</li></ul><h3 id="exporting-a-lorebook" tabindex="-1">Exporting a Lorebook <a class="header-anchor" href="#exporting-a-lorebook" aria-label="Permalink to &quot;Exporting a Lorebook&quot;">​</a></h3><ol><li>Open the character with the lorebook you want to export.</li><li>Go to the <strong>Lorebook</strong> tab.</li><li>Click <strong>Export</strong> in the lorebook toolbar.</li><li>The lorebook is exported as a JSON file compatible with SillyTavern and other tools.</li></ol><p>Empty character books are automatically filtered out during export.</p><h3 id="importing-a-lorebook" tabindex="-1">Importing a Lorebook <a class="header-anchor" href="#importing-a-lorebook" aria-label="Permalink to &quot;Importing a Lorebook&quot;">​</a></h3><ol><li>Open the character where you want to import the lorebook.</li><li>Go to the <strong>Lorebook</strong> tab.</li><li>Click <strong>Import</strong> in the lorebook toolbar.</li><li>Select a JSON file containing lorebook data.</li></ol><div class="tip custom-block"><p class="custom-block-title">Supported Formats</p><p>Lorebook import accepts JSON files with either:</p><ul><li>A <code>character_book</code> object</li><li>An <code>entries</code> array</li></ul></div><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/features/creator-notes">Creator Notes preview</a></li><li><a href="/CharacterVault/docs/features/ai-assistant">AI Assistant — Orion</a></li><li><a href="/CharacterVault/docs/configuration/ai-setup">Configure AI provider</a></li></ul>',41)])])}const u=e(i,[["render",n]]);export{p as __pageData,u as default};
